import assert from 'node:assert/strict';import fs from 'node:fs';
const s=fs.readFileSync('.github/scripts/observation-planner-forecast-f4c-acquire.mjs','utf8');const w=fs.readFileSync('.github/workflows/bkl-031-f4-c-acquire-once.yml','utf8');const d=fs.readFileSync('docs/architecture/scientific-assets/BKL-031-F4-C-One-Request-Generalized-Forecast-Acquisition-Gate.md','utf8');
assert.equal((s.match(/fetch\(/g)??[]).length,1,'gate must contain exactly one fetch site');for(const x of ["latitude:'42.0'","longitude:'12.0'","redirect:'manual'","maxRequests:1","maxResponseBytes:2000000","F4C_ONE_GENERALIZED_REQUEST","protectedSiteUsed:false"])assert.ok(s.includes(x),`script missing ${x}`);for(const x of ['workflow_dispatch:','expected_main_sha:','run_initialisation_utc:','git ls-remote origin refs/heads/main','retention-days: 7'])assert.ok(w.includes(x),`workflow missing ${x}`);assert.ok(!w.includes('schedule:'),'workflow must not be scheduled');for(const x of ['**REVIEW CANDIDATE — NOT EXECUTED**','Exactly one HTTPS GET','Synthetic/generalized `42.0, 12.0`','one fetch site','Stop after the evidence artifact'])assert.ok(d.includes(x),`document missing ${x}`);const r=JSON.parse(fs.readFileSync('.github/roadmap/roadmap-source.json','utf8'));assert.equal(r.nextMilestone,'BKL-031 F4-C one-request generalized acquisition gate acceptance');assert.ok(r.milestones.some(x=>x.id==='M-BKL031-F4-C-ACQUISITION-GATE'));console.log('BKL-031 F4-C gate verified: one generalized request, exact main/run/confirmation, no protected-site input, no schedule; NOT EXECUTED.');